/* Mia Chat Design System — vars --mia-* centralizadas (rose rubi, tipografia) */
@import './features/mia/styles/mia-chat.css';

@tailwind base;
@tailwind components;
@tailwind utilities;

/* Leaflet Map Styles */
.leaflet-container {
  height: 100%;
  width: 100%;
  z-index: 1;
}

.leaflet-control-container {
  z-index: 1000;
}

.leaflet-popup-content-wrapper {
  border-radius: 8px;
}

.leaflet-popup-tip {
  background: white;
}

/* Momma Design System - Cores e estilos baseados na identidade visual */

@layer base {
  :root {
    /* Sistema de cores Pantone da empresa - Modo Claro */
    /* Cores Pantone convertidas para HSL (regra 70-20-10 aprimorada) */
    --pantone-primary: 35 33% 55%;    /* #B49364 - Marrom dourado (20%) */
    --pantone-background: 46 63% 95%; /* #F3ECD4 - Bege claro (70%) */
    --pantone-accent: 133 17% 33%;    /* #33733F - Verde escuro (10%) */
    --pantone-foreground: 60 7% 20%;   /* #3C3B34 - Cinza escuro (texto) */

    /* Sistema de cores baseado na regra 70-20-10 (sem verde oliva) */
    --background: 46 63% 95%; /* Bege claro (70%) - #F3ECD4 */
    --foreground: 60 7% 20%;  /* Cinza escuro - #3C3B34 */

    --card: 46 63% 98%; /* Bege muito claro */
    --card-foreground: 60 7% 20%;

    --popover: 46 63% 98%;
    --popover-foreground: 60 7% 20%;

    --primary: 35 33% 55%; /* Marrom dourado (20%) - #B49364 */
    --primary-foreground: 46 63% 98%; /* Texto claro sobre marrom */

    --secondary: 35 25% 45%; /* Marrom médio (substituto harmonioso) */
    --secondary-foreground: 46 63% 98%; /* Texto claro */

    --muted: 46 40% 92%; /* Bege suave */
    --muted-foreground: 35 20% 40%; /* Marrom escuro suave */

    --accent: 133 17% 33%; /* Verde escuro (10%) - #33733F */
    --accent-foreground: 46 63% 98%; /* Texto claro sobre verde escuro */

    --destructive: 0 75% 60%;
    --destructive-foreground: 0 0% 100%;

    --success: 133 17% 33%; /* Verde escuro para sucesso */
    --success-foreground: 46 63% 98%; /* Texto claro */

    --warning: 35 33% 55%; /* Marrom dourado para avisos */
    --warning-foreground: 46 63% 98%; /* Texto claro */

    --border: 35 25% 80%; /* Borda marrom claro */
    --input: 46 30% 90%; /* Input bege */
    --ring: 35 33% 55%; /* Ring marrom dourado */

    --radius: 0.75rem; /* Border radius aumentado para design moderno */

    --sidebar-background: 46 63% 97%; /* Bege claro */
    --sidebar-foreground: 60 7% 20%; /* Cinza escuro */
    --sidebar-primary: 35 33% 55%; /* Marrom dourado */
    --sidebar-primary-foreground: 46 63% 98%; /* Texto claro */
    --sidebar-accent: 133 17% 33%; /* Verde escuro */
    --sidebar-accent-foreground: 46 63% 98%; /* Texto claro */
    --sidebar-border: 35 25% 85%; /* Borda marrom claro */
    --sidebar-ring: 35 33% 55%; /* Ring marrom dourado */

    /* Tokens de cores da empresa para Tailwind */
    --company-verde-escuro: 133 17% 33%;
    --company-verde-claro: 133 17% 45%;
    --company-bege: 46 63% 95%;
    --company-marrom: 35 33% 55%;
    --company-cinza-escuro: 60 7% 20%;

    /* Tokens Momma utilizados em gradientes e botões especiais */
    --momma-primary: var(--primary);
    --momma-primary-dark: 35 33% 45%;
    --momma-gradient-start: var(--primary);
    --momma-gradient-end: var(--accent);

    /* ── MIA Chat Custom Properties ── */
    /* ── MIA vars — definição canônica em src/features/mia/styles/mia-chat.css.
       NÃO redefinir aqui para evitar override do design system da Mia. ── */
  }

  .dark {
    /* Sistema de cores Pantone da empresa - Modo Escuro */
    /* Inversão da regra 70-20-10 para modo escuro (sem verde oliva) */
    --background: 60 7% 15%; /* Cinza muito escuro (70%) - #262624 */
    --foreground: 46 63% 90%; /* Bege claro para texto */

    /* Cards - tons escuros com toques quentes */
    --card: 35 15% 20%; /* Marrom escuro (20%) */
    --card-foreground: 46 63% 90%; /* Texto bege claro */

    --popover: 35 15% 18%; /* Marrom um pouco mais escuro */
    --popover-foreground: 46 63% 90%;

    /* Primário - marrom dourado mais suave no escuro */
    --primary: 35 33% 45%; /* Marrom dourado escuro (20%) */
    --primary-foreground: 46 63% 98%; /* Texto muito claro */

    /* Secundário - marrom médio escuro */
    --secondary: 35 25% 35%; /* Marrom médio escuro */
    --secondary-foreground: 46 63% 98%; /* Texto muito claro */

    /* Tons suaves e muted */
    --muted: 35 15% 22%; /* Marrom escuro suave */
    --muted-foreground: 46 40% 75%; /* Bege médio */

    /* Accent - verde escuro mais vibrante */
    --accent: 133 17% 40%; /* Verde escuro intenso (10%) */
    --accent-foreground: 46 63% 98%; /* Texto muito claro */

    /* Destructive - mantido consistente */
    --destructive: 0 70% 42%;
    --destructive-foreground: 0 0% 100%;

    /* Success - verde escuro */
    --success: 133 17% 40%; /* Verde escuro intenso */
    --success-foreground: 46 63% 98%; /* Texto muito claro */

    /* Warning - marrom dourado */
    --warning: 35 33% 45%; /* Marrom dourado escuro */
    --warning-foreground: 46 63% 98%; /* Texto muito claro */

    /* Bordas - marrom escuro */
    --border: 35 15% 25%; /* Borda marrom escuro */
    --input: 35 15% 22%; /* Input marrom escuro */
    --ring: 35 33% 45%; /* Ring marrom dourado */

    /* Sidebar - tons consistentes com modo escuro */
    --sidebar-background: 35 15% 18%; /* Marrom muito escuro */
    --sidebar-foreground: 46 63% 90%; /* Texto bege */
    --sidebar-primary: 35 33% 45%; /* Marrom dourado escuro */
    --sidebar-primary-foreground: 46 63% 98%; /* Texto muito claro */
    --sidebar-accent: 133 17% 40%; /* Verde escuro intenso */
    --sidebar-accent-foreground: 46 63% 98%; /* Texto muito claro */
    --sidebar-border: 35 15% 22%; /* Borda marrom */
    --sidebar-ring: 35 33% 45%; /* Ring marrom dourado */

    /* Tokens de cores da empresa para Tailwind - Modo Escuro */
    --company-verde-escuro: 133 17% 40%;
    --company-verde-claro: 133 17% 50%;

